import React from 'react';

import { Link } from 'react-router-dom';

import { getSharedEquipSets } from '@apps/Hiking/@services/equip.service';
import { getHikingFieldsAsync } from '@apps/Hiking/@services/hiking.service';
import { ISharedEquipSet } from '@apps/Hiking/@types/equip.types';
import PageLoader from '@components/PageLoader';
import PohAva from '@ui-kit/Ava';
import Breadcrumb from '@ui-kit/Breadcrumb';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

const HikingEquipShared = ({ id_hiking }: { id_hiking: number }) => {
  const [loading, setLoading] = React.useState(true);
  const [hikingName, setHikingName] = React.useState('');
  const [items, setItems] = React.useState<ISharedEquipSet[]>([]);

  React.useEffect(() => {
    const start = async () => {
      try {
        setLoading(true);
        const { name = 'unknown' } = await getHikingFieldsAsync(id_hiking, 'name');
        setHikingName(name);
        const res = await getSharedEquipSets(id_hiking);
        setItems(res);
      } finally {
        setLoading(false);
      }
    };
    start();
  }, [id_hiking]);

  if (loading) {
    return <PageLoader />;
  }

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingName },
          {
            href: `/hiking/${id_hiking}/equip/shared`,
            text: 'Подборки снаряжения для похода',
            active: true,
          },
        ]}
      />
      <h3 className="mb-3">Снаряжение для похода «{hikingName}»</h3>

      <PohRow>
        <PohCol sm={12}>
          {items == null && <PageLoader />}
          {items?.length === 0 && <Empty>Нет сборок</Empty>}
          {items?.length > 0 && (
            <PohList
              data={items.map((item) => ({
                key: item.id,
                as: Link,
                to: `/hiking/${id_hiking}/equip/${item.id_set}`,
                content: (
                  <div className="d-flex justify-content-between align-items-center">
                    <div>
                      <PohAva
                        className="my-n2 ms-n2 me-2"
                        src={item.userFrom.photo}
                        alt={`${item.userFrom.name} ${item.userFrom.surname}`}
                      />
                      {`${item.userFrom.name} ${item.userFrom.surname}`}
                      {' ➟ '}
                      {item?.userTo ? `${item.userTo.name} ${item.userTo.surname}` : 'Все'}
                    </div>
                    <div>
                      {item?.userTo && (
                        <PohAva
                          className="my-n2 ms-2 me-n2"
                          src={item.userTo.photo}
                          alt={`${item.userTo.name} ${item.userTo.surname}`}
                        />
                      )}
                    </div>
                  </div>
                ),
              }))}
            />
          )}
        </PohCol>
      </PohRow>
    </PohContainer>
  );
};

export default HikingEquipShared;
